import React, { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import './SendMoney.css';

function SendMoney() {
  const navigate = useNavigate();

  // Form State
  const [formData, setFormData] = useState({
    sourceWallet: '',
    recipientWallet: '',
    amount: '',
    recipientName: '',
    phoneNumber: '',
    description: '',
  });

  // UI State
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);
  const [showConfirmation, setShowConfirmation] = useState(false);
  const [selectedWalletBalance, setSelectedWalletBalance] = useState(0);

  // Mock Wallet Data
  const myWallets = [
    { id: 1, name: 'Personal Wallet', balance: 5000, currency: 'USD' },
    { id: 2, name: 'Business Wallet', balance: 10000, currency: 'USD' },
    { id: 3, name: 'Savings Wallet', balance: 3000, currency: 'USD' },
  ];

  const recipientWallets = [
    { id: 1, name: 'John Doe', walletId: 'JD123', type: 'Personal' },
    { id: 2, name: 'Jane Smith', walletId: 'JS456', type: 'Business' },
    { id: 3, name: 'Add New Recipient', walletId: 'new', type: 'New' },
  ];

  // Validation State
  const [validationErrors, setValidationErrors] = useState({});

  // Update selected wallet balance
  useEffect(() => {
    const wallet = myWallets.find((w) => w.id === parseInt(formData.sourceWallet));
    setSelectedWalletBalance(wallet ? wallet.balance : 0);
  }, [formData.sourceWallet]);

  // Form Validation
  const validateForm = useCallback(() => {
    const errors = {};
    const phoneRegex = /^\+?[1-9]\d{9,13}$/;

    if (!formData.amount) {
      errors.amount = 'Amount is required';
    } else if (parseFloat(formData.amount) <= 0) {
      errors.amount = 'Amount must be greater than 0';
    } else if (parseFloat(formData.amount) > selectedWalletBalance) {
      errors.amount = 'Insufficient balance';
    }

    if (!formData.phoneNumber) {
      errors.phoneNumber = 'Phone number is required';
    } else if (!phoneRegex.test(formData.phoneNumber)) {
      errors.phoneNumber = 'Invalid phone number format';
    }

    if (!formData.recipientName.trim()) {
      errors.recipientName = 'Recipient name is required';
    } else if (formData.recipientName.length < 2) {
      errors.recipientName = 'Name is too short';
    }

    setValidationErrors(errors);
    return Object.keys(errors).length === 0;
  }, [formData, selectedWalletBalance]);

  // Handle form field changes
  const handleChange = ({ target: { name, value } }) => {
    setFormData((prev) => ({ ...prev, [name]: value }));
    if (validationErrors[name]) {
      setValidationErrors((prev) => ({ ...prev, [name]: '' }));
    }
  };

  // Handle form submission
  const handleSubmit = async (e) => {
    e.preventDefault();
    setError(null);

    if (!validateForm()) return;

    setShowConfirmation(true);
  };

  // Confirm and process the transfer
  const handleConfirmTransfer = async () => {
    setIsLoading(true);
    try {
      await new Promise((resolve) => setTimeout(resolve, 1500)); // Simulate API call
      setFormData({
        sourceWallet: '',
        recipientWallet: '',
        amount: '',
        recipientName: '',
        phoneNumber: '',
        description: '',
      });
      navigate('/transfer-success', {
        state: {
          amount: formData.amount,
          recipient: formData.recipientName,
        },
      });
    } catch {
      setError('Transfer failed. Please try again.');
    } finally {
      setIsLoading(false);
      setShowConfirmation(false);
    }
  };

  // Confirmation Modal
  const ConfirmationModal = () => (
    <div className="modal-overlay">
      <div className="modal-content">
        <h3>Confirm Transfer</h3>
        <div className="transfer-details">
          <p>
            <strong>From:</strong>{' '}
            {myWallets.find((w) => w.id === parseInt(formData.sourceWallet))?.name}
          </p>
          <p>
            <strong>To:</strong> {formData.recipientName}
          </p>
          <p>
            <strong>Amount:</strong> ${formData.amount}
          </p>
          <p>
            <strong>Phone:</strong> {formData.phoneNumber}
          </p>
          {formData.description && (
            <p>
              <strong>Description:</strong> {formData.description}
            </p>
          )}
        </div>
        <div className="modal-actions">
          <button
            onClick={() => setShowConfirmation(false)}
            className="cancel-button"
            disabled={isLoading}
          >
            Cancel
          </button>
          <button
            onClick={handleConfirmTransfer}
            className="confirm-button"
            disabled={isLoading}
          >
            {isLoading ? 'Processing...' : 'Confirm Transfer'}
          </button>
        </div>
      </div>
    </div>
  );

  return (
    <div className="send-money-page">
      <h2>Send Money</h2>
      {error && <div className="error-banner">{error}</div>}
      <form onSubmit={handleSubmit} className="send-money-form">
        <div className="form-group">
          <label htmlFor="sourceWallet">From Wallet</label>
          <select
            id="sourceWallet"
            name="sourceWallet"
            value={formData.sourceWallet}
            onChange={handleChange}
            required
          >
            <option value="">Select your wallet</option>
            {myWallets.map((wallet) => (
              <option key={wallet.id} value={wallet.id}>
                {wallet.name} - Balance: ${wallet.balance}
              </option>
            ))}
          </select>
          {formData.sourceWallet && (
            <div className="wallet-balance">
              Available Balance: ${selectedWalletBalance}
            </div>
          )}
        </div>
        {/* Remaining form fields */}
        {/* Similar structure for recipientWallet, recipientName, phoneNumber, amount, and description */}
        <button type="submit" className="submit-button" disabled={isLoading}>
          {isLoading ? 'Processing...' : 'Send Money'}
        </button>
      </form>
      {showConfirmation && <ConfirmationModal />}
    </div>
  );
}

export default SendMoney;
